namespace ghidra.app.plugin.core.symboltree.actions;





using docking.action;
using docking.action;
using generic.theme;
using ghidra.app.cmd.refs;
using ghidra.app.plugin.core.symboltree;
using ghidra.app.plugin.core.symboltree.nodes;
using ghidra.framework.cmd;
using ghidra.framework.main;
using ghidra.framework.main;
using ghidra.framework.model;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util;

public class SetExternalProgramAction : SymbolTreeContextAction {
	private static Icon EDIT_ICON = new GIcon("icon.plugin.symboltree.set.external");
	private SymbolTreePlugin plugin;
	private SymbolTreeProvider provider;

	public SetExternalProgramAction(SymbolTreePlugin plugin, SymbolTreeProvider provider) : base("Set External Program", plugin.getName())
    {
		this.plugin = plugin;
		this.provider = provider;
		this.setPopupMenuData(
			new MenuData(new string[] { "Set External Program" }, EDIT_ICON, "0External"));

		this.setToolBarData(new ToolBarData(EDIT_ICON, null));

		setEnabled(false);
	}

	/* @Override */
	public bool isEnabledForContext(SymbolTreeActionContext context) {

		TreePath[] selectionPaths = context.getSelectedSymbolTreePaths();
		if (selectionPaths.length == 1) {
			object @object = selectionPaths[0].getLastPathComponent();
			if (@object is LibrarySymbolNode) {
				return true;
			}
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(SymbolTreeActionContext context) {
		TreePath[] selectionPaths = context.getSelectedSymbolTreePaths();
		if (selectionPaths.length != 1) {
			return;
		}
		object @object = selectionPaths[0].getLastPathComponent();
		if (!(@object is LibrarySymbolNode)) {
			return;
		}

		LibrarySymbolNode libraryNode = (LibrarySymbolNode) @object;
		string externalName = libraryNode.getName();
		Program program = plugin.getProgram();
		ExternalManager externalManager = program.getExternalManager();
		string externalLibraryPath = externalManager.getExternalLibraryPath(externalName);

		ProgramFileChooser dialog = new ProgramFileChooser(provider.getComponent(),
			"Choose External Program (" + externalName + ")");

		dialog.setSearchText(externalName);

		dialog.addOkActionListener(e1 => {
			DomainFile domainFile = dialog.getDomainFile();
			if (domainFile == null) {
				return;
			}
			string pathName = domainFile.toString();
			dialog.close();
			if (!pathName.equals(externalLibraryPath)) {
				Command<Program> cmd =
					new SetExternalNameCmd(externalName, domainFile.getPathname());
				plugin.getTool().execute(cmd, plugin.getProgram());
			}
		});
		dialog.setHelpLocation(new HelpLocation("SymbolTreePlugin", "ChooseExternalProgram"));

		if (externalLibraryPath != null) {
			SwingUtilities.invokeLater(() => {
				Project project = AppInfo.getActiveProject();
				ProjectData pd = project.getProjectData();
				DomainFile domainFile = pd.getFile(externalLibraryPath);
				if (domainFile != null) {
					dialog.selectDomainFile(domainFile);
				}
			});
		}

		plugin.getTool().showDialog(dialog);
	}
}
